/* Generated by Dudaport: submits Duda-style forms to the shared lead service (same domain, POST /v1/lead) and shows the
   form's own success block. Without JavaScript the plain POST still works (the service answers with a 303). */
(function () {
  'use strict';
  function box(form, cls) {
    var scope = form.closest('[class*="dmform"]') || form.parentNode || form;
    return form.querySelector('.' + cls) || (scope && scope.querySelector('.' + cls));
  }
  document.querySelectorAll('form[data-ls-form]').forEach(function (form) {
    var ts = form.querySelector('input[name="ts"]');
    if (ts) ts.value = String(Date.now());
    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var btn = form.querySelector('[type="submit"], button:not([type])');
      if (btn) btn.disabled = true;
      fetch(form.getAttribute('action') || '/v1/lead', {
        method: 'POST', headers: { 'Accept': 'application/json' }, credentials: 'same-origin',
        body: new URLSearchParams(new FormData(form))
      }).then(function (r) {
        return r.json().catch(function () { return {}; }).then(function (d) { return { ok: r.ok && d.ok !== false, message: d.message }; });
      }).catch(function () {
        return { ok: false, message: 'That didn\u2019t work. Please try again.' };
      }).then(function (res) {
        if (btn) btn.disabled = false;
        var ok = box(form, 'dmform-success'), bad = box(form, 'dmform-error');
        if (res.ok) {
          if (ok) { ok.hidden = false; ok.style.display = 'block'; }
          form.reset();
          form.style.display = ok && !form.contains(ok) ? 'none' : form.style.display;
          return;
        }
        if (!bad) {
          bad = document.createElement('p');
          bad.className = 'dmform-error ls-form-error';
          bad.setAttribute('role', 'alert');
          form.appendChild(bad);
        }
        bad.hidden = false; bad.style.display = 'block';
        if (res.message) bad.textContent = res.message;
      });
    });
  });
})();
